UPDATE `locales_item` SET `name_loc1`='넬타리온의 눈물', `name_loc4`='奈萨里奥之泪', `name_loc5`='奈薩里奧之淚', `name_loc7`='Lágrima de Neltharion', `description_loc1`='은색 액체가 깨지지 않는 검은 껍질 속에 흐르고 있습니다. 주위로 극한의 힘의 정기가 뿜어져 나옵니다.', `description_loc4`='银色的液体在乌黑的外壳中涌动，这件物品非常纯净，它散发着强大的能量。', `description_loc5`='銀色的液體在烏黑的外殼中湧動，這件物品非常純淨，它散發著強大的能量。', `description_loc7`='Un líquido plateado fluye dentro del impenetrable caparazón de ébano. El objeto parece puro. Irradia pureza. Irradia una esencia de gran poder.' WHERE `entry`=19379;
